        data['packages'].append(dict(id='twilightforest:'+key,display_name=title,owner=key,primary_classification=classification,facts=keys+['authority','compatibility'],classes=classes,parameters=params,gates=gates,relation='Pinned native primitives and custom caller eligibility; materially distinct source/admission retained, no manufactured source or HP outcome.',primary_test_source=title+' through actual registered native world/interaction path',alternate_sources=['native denied/allowed controls','actual reload and event mutation','native source and return-value observations']))
